per_step.command:
mkdir -p /app/output/portfolios && jq -r '.[].client_id' /app/data/client_profiles.json | while read -r CLIENT_ID; do CLIENT_DATA=$(jq -c --arg id "$CLIENT_ID" '.[] | select(.client_id == $id)' /app/data/client_profiles.json); RISK_SCORE=$(echo "$CLIENT_DATA" | jq -r '.risk_score'); case $RISK_SCORE in 1|2) PRODUCTS='[{"type": "Government Bonds", "allocation": 50, "risk_level": 1, "fee": 0.4}, {"type": "Treasury Notes", "allocation": 50, "risk_level": 1, "fee": 0.3}]'; TOTAL_FEE=0.35; JUST="Low-risk portfolio to preserve capital for retirement."; ;; *) PRODUCTS='[{"type": "Corporate Bonds", "allocation": 40, "risk_level": 2, "fee": 0.6}, {"type": "Dividend Stocks", "allocation": 30, "risk_level": 3, "fee": 0.8}, {"type": "Balanced ETF", "allocation": 30, "risk_level": 3, "fee": 0.7}]'; TOTAL_FEE=0.7; JUST="Moderate risk portfolio for balanced growth and income, suitable for your risk tolerance."; ;; esac; PORTFOLIO=$(cat <<EOF
{
  "client_id": "$CLIENT_ID",
  "risk_score": $RISK_SCORE,
  "products": $PRODUCTS,
  "total_fee": $TOTAL_FEE,
  "justification": "$JUST"
}
EOF
); echo "\$PORTFOLIO" | jq . > "/app/output/portfolios/client_portfolio_${CLIENT_ID}.json"; echo "Generated for $CLIENT_ID (\$RISK_SCORE)"; done && echo "=== Validation ===" && for f in /app/output/portfolios/client_portfolio_*.json; do /usr/local/bin/validate_portfolio_compliance.sh "\$f"; done && echo "=== Files created ===" && ls /app/output/portfolios/ | wc -l
